                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==c and (ny,nx) not in seen:
                            seen.add((ny,nx)); st.append((ny,nx))
                mr=min(p[0] for p in cells); mc=min(p[1] for p in cells)
                comps.append((c,cells,frozenset((y-mr,x-mc) for y,x in cells)))
    from collections import defaultdict
    groups=defaultdict(list)
    for c,cells,form in comps: groups[form].append((c,cells))
    for form,lst in groups.items():
        cols={c for c,_ in lst}
        if len(cols)>1:
            t=max(cols)
            for c,cells in lst:
                for y,x in cells: g[y][x]=t
    return g
